CREATE POLICY customer_assets_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='customer-assets' AND (storage.foldername(name))[1]=(SELECT auth.uid())::text);
CREATE POLICY customer_assets_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='customer-assets' AND (storage.foldername(name))[1]=(SELECT auth.uid())::text);
CREATE POLICY customer_assets_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='customer-assets' AND (storage.foldername(name))[1]=(SELECT auth.uid())::text);
CREATE FUNCTION public.admin_summary() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT jsonb_build_object('customers',(SELECT count(*) FROM public.profiles),'projects',(SELECT count(*) FROM public.customer_projects WHERE kind IN ('motion','overlay')),'generations',(SELECT count(*) FROM public.generations),'paid_orders',(SELECT count(*) FROM public.payment_orders WHERE status='paid'),'input_tokens',(SELECT coalesce(sum(input_tokens),0) FROM public.usage_costs),'output_tokens',(SELECT coalesce(sum(output_tokens),0) FROM public.usage_costs)) WHERE public.has_role(auth.uid(),'admin') $$;
REVOKE ALL ON FUNCTION public.admin_summary() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_summary() TO authenticated,service_role;